-- Manufacturing Quick Report view - GENERATED by `npm run erp:mfg-view` from the header AND detail tables of this database.
-- Do not edit by hand: change DETAIL_OVERRIDES in backend/src/services/mfgViewBuilder.ts and generate it again.
IF OBJECT_ID('dbo.v_manufacturing_quick', 'V') IS NOT NULL DROP VIEW dbo.v_manufacturing_quick;
GO
CREATE VIEW dbo.v_manufacturing_quick AS
WITH txn AS (
  SELECT tbl, code, name FROM (VALUES
    ('fAdjhed', '?', N'Lami. FG Adjustments Addition Entry'),
    ('fAdjhed', '?', N'Return Accept Quantity In Entry'),
    ('fAdjhed', '14', N'Return Reject Quantity In Entry'),
    ('fAdjhed', '15', N'FG Adjustments Addition Entry'),
    ('fAdjhed', '?', N'FG Adjustments Deduction Entry'),
    ('fAdjhed', '?', N'SF Adjustments Deduction Entry'),
    ('fmfgjbtrnhed', '?', N'Lami. FG Job Transfer'),
    ('fmfgjbtrnhed', '93', N'FG Job Transfer'),
    ('fmWstInHed', '17', N'FG To Waste'),
    ('fmWstInHed', '43', N'Wastage In Job Wise'),
    ('fIssRHed', '33', N'Acceptance Note'),
    ('fIssRHed', '?', N'INK Return Entry'),
    ('fRIssHed', '34', N'Issue - Coco'),
    ('fRIssHed', '?', N'Issue Extra - Coco'),
    ('fmpipAshed', '48', N'Pipe Build Assembly'),
    ('fmpipAshed', '77', N'Pipe Waste Build Allocation'),
    ('FiRIssHed', '64', N'INK Issue Note'),
    ('FiRIssHed', '?', N'Issue Note'),
    ('flRIssHed', '68', N'Issue Note - Standard (Lami)'),
    ('flRIssHed', '?', N'Issue Note - Extra (Lami)'),
    ('fmStTrnhed', '80', N'Site Transfer FG'),
    ('fmStTrnhed', '96', N'Site Transfer WIP'),
    ('frDispHed', '?', N'Sample Gate Pass'),
    ('frDispHed', '?', N'Dispatch - Stretch Film'),
    ('frDispHed', '54', N'Dispatch - Local Sales'),
    ('frDispHed', '56', N'Dispatch - Walk In'),
    ('frDispHed', '?', N'Dispatch - Pipes'),
    ('frDispHed', '62', N'Dispatch Walking-Pipe'),
    ('frDispHed', '72', N'Dispatch Note - Coco'),
    ('frDispHed', '86', N'Dispatch Note - Lamination'),
    ('frDispHed', '?', N'Dispatch Note - Trading'),
    ('frDispHed', '?', N'Dispatch Return Note'),
    ('frDispHed', '?', N'Dispatch Ret. Note-Pipe')
  ) v(tbl, code, name)
)
SELECT
    CAST('fCsMatHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Customer Mat. In' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fCsMatHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(COALESCE(NULLIF(RTRIM(deb.[DebName]), ''), RTRIM(h.[DebCode])) AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(RTRIM(h.[RefNo1]) AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(COALESCE(NULLIF(RTRIM(h.[ItemCode]), ''), NULLIF(RTRIM(d.[ItemCode]), '')) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(CASE WHEN d.[RefNo] IS NULL THEN h.[Qty] ELSE d.[Qty] END AS numeric(18,4)) AS [qtyKg],
    CAST(NULL AS numeric(18,4)) AS [pieces],
    CAST(RTRIM(h.[SiteCode]) AS nvarchar(200)) AS [site],
    CAST(NULL AS nvarchar(200)) AS [stage],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [location],
    CAST(RTRIM(h.[comcode]) AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fCsMatHed] h
  LEFT JOIN dbo.[fCsMatDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.[fDebtor] deb ON deb.[DebCode] = h.[DebCode]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
    CAST('fSoBldAsHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'SO Build Assembly' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fSoBldAsHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(NULL AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(COALESCE(NULLIF(RTRIM(h.[RefNo1]), ''), NULLIF(RTRIM(d.[RefNo1]), '')) AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(COALESCE(NULLIF(RTRIM(h.[ItemCode]), ''), NULLIF(RTRIM(d.[ItemCode]), '')) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(RTRIM(h.[machcode]) AS nvarchar(200)) AS [machine],
    CAST(CASE WHEN (d.[RefNo] IS NULL OR d.[_ln] = 1) THEN h.[QtyW] END AS numeric(18,4)) AS [qtyKg],
    CAST(CASE WHEN d.[RefNo] IS NULL THEN h.[Qty] ELSE d.[Qty] END AS numeric(18,4)) AS [pieces],
    CAST(COALESCE(NULLIF(RTRIM(h.[SiteCode]), ''), NULLIF(RTRIM(d.[SiteCode]), '')) AS nvarchar(200)) AS [site],
    CAST(RTRIM(h.[StagCode]) AS nvarchar(200)) AS [stage],
    CAST(COALESCE(NULLIF(RTRIM(h.[LocCode]), ''), NULLIF(RTRIM(d.[LocCode]), '')) AS nvarchar(200)) AS [location],
    CAST(RTRIM(h.[ComCode]) AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fSoBldAsHed] h
  LEFT JOIN (SELECT x.*, ROW_NUMBER() OVER (PARTITION BY x.[RefNo] ORDER BY x.[RecordId]) AS [_ln] FROM dbo.[fSoBldAsDet] x) d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
