    CAST(RTRIM(h.[StagCode]) AS nvarchar(200)) AS [stage],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [location],
    CAST(NULL AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fmSFgTranHed] h
  LEFT JOIN (SELECT x.*, ROW_NUMBER() OVER (PARTITION BY x.[RefNo] ORDER BY x.[RecordId]) AS [_ln] FROM dbo.[fmSFgTranDet] x) d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.[fDebtor] deb ON deb.[DebCode] = h.[DebCode]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
    CAST('fAdjhed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(COALESCE(m.name, N'Adjustment Entry') AS nvarchar(200)) AS [type],
