    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fAdjhed] h
  LEFT JOIN dbo.[fAdjDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]
  LEFT JOIN txn m ON m.tbl = 'fAdjhed' AND m.code = RTRIM(h.[TxnType])

  UNION ALL

  SELECT
