  LEFT JOIN dbo.[fmRStTrnDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
    CAST('fOpnhed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Job Wise Opening Balance' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fOpnhed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(COALESCE(NULLIF(RTRIM(deb.[DebName]), ''), RTRIM(h.[DebCode])) AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(COALESCE(NULLIF(RTRIM(h.[JobNo]), ''), NULLIF(RTRIM(d.[JobNo]), '')) AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(RTRIM(d.[ItemCode]) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(NULL AS numeric(18,4)) AS [qtyKg],
    CAST(NULL AS numeric(18,4)) AS [pieces],
    CAST(COALESCE(NULLIF(RTRIM(h.[SiteCode]), ''), NULLIF(RTRIM(d.[SiteCode]), '')) AS nvarchar(200)) AS [site],
    CAST(RTRIM(h.[StagCode]) AS nvarchar(200)) AS [stage],
    CAST(COALESCE(NULLIF(RTRIM(h.[LocCode]), ''), NULLIF(RTRIM(d.[LocCode]), '')) AS nvarchar(200)) AS [location],
    CAST(RTRIM(h.[ComCode]) AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fOpnhed] h
  LEFT JOIN dbo.[fstkin] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.[fDebtor] deb ON deb.[DebCode] = h.[DebCode]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]

  UNION ALL

  SELECT
    CAST('fmLFgTranHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'FG Transfer (Lami)' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fmLFgTranHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(COALESCE(NULLIF(RTRIM(deb.[DebName]), ''), RTRIM(h.[DebCode])) AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(RTRIM(h.[RefNo1]) AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(COALESCE(NULLIF(RTRIM(h.[ItemCode]), ''), NULLIF(RTRIM(d.[ItemCode]), '')) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(CASE WHEN d.[RefNo] IS NULL THEN h.[Qty] ELSE d.[Qty] END AS numeric(18,4)) AS [qtyKg],
    CAST(CASE WHEN (d.[RefNo] IS NULL OR d.[_ln] = 1) THEN h.[QtyPc] END AS numeric(18,4)) AS [pieces],
    CAST(RTRIM(h.[SiteCode]) AS nvarchar(200)) AS [site],
    CAST(RTRIM(h.[StagCode]) AS nvarchar(200)) AS [stage],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [location],
    CAST(NULL AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fmLFgTranHed] h
  LEFT JOIN (SELECT x.*, ROW_NUMBER() OVER (PARTITION BY x.[RefNo] ORDER BY x.[RecordId]) AS [_ln] FROM dbo.[fmLFgTranDet] x) d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.[fDebtor] deb ON deb.[DebCode] = h.[DebCode]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
    CAST('flmWstInHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Waste In - Lami' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('flmWstInHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(NULL AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(NULL AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(RTRIM(d.[ItemCode]) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(d.[Qty] AS numeric(18,4)) AS [qtyKg],
    CAST(NULL AS numeric(18,4)) AS [pieces],
    CAST(RTRIM(h.[SiteCode]) AS nvarchar(200)) AS [site],
    CAST(NULL AS nvarchar(200)) AS [stage],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [location],
    CAST(RTRIM(h.[ComCode]) AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[flmWstInHed] h
  LEFT JOIN dbo.[flmWstInDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]

  UNION ALL

  SELECT
    CAST('fmSizTranHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Pipe Size Transfer' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fmSizTranHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(NULL AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(NULL AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(COALESCE(NULLIF(RTRIM(h.[ItemCode]), ''), NULLIF(RTRIM(d.[ItemCode]), '')) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(CASE WHEN (d.[RefNo] IS NULL OR d.[_ln] = 1) THEN h.[TotWeight] END AS numeric(18,4)) AS [qtyKg],
    CAST(CASE WHEN (d.[RefNo] IS NULL OR d.[_ln] = 1) THEN h.[TotQty] END AS numeric(18,4)) AS [pieces],
    CAST(RTRIM(d.[SiteCode]) AS nvarchar(200)) AS [site],
    CAST(RTRIM(h.[StagCode]) AS nvarchar(200)) AS [stage],
    CAST(RTRIM(d.[LocCode]) AS nvarchar(200)) AS [location],
    CAST(RTRIM(h.[ComCode]) AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fmSizTranHed] h
  LEFT JOIN (SELECT x.*, ROW_NUMBER() OVER (PARTITION BY x.[RefNo] ORDER BY x.[RecordId]) AS [_ln] FROM dbo.[fmSizTrandet] x) d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
    CAST('fmPStTrnhed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(N'Site Transfer Entry-Pipe' AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('fmPStTrnhed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(NULL AS nvarchar(200)) AS [customer],
    CAST(NULL AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(COALESCE(NULLIF(RTRIM(h.[RefNo1]), ''), NULLIF(RTRIM(d.[RefNo1]), '')) AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(COALESCE(NULLIF(RTRIM(h.[ItemCode]), ''), NULLIF(RTRIM(d.[ItemCode]), '')) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(CASE WHEN d.[RefNo] IS NULL THEN h.[Qty] ELSE d.[Qty] END AS numeric(18,4)) AS [qtyKg],
    CAST(CASE WHEN d.[RefNo] IS NULL THEN h.[QtyPc] ELSE d.[Qtypc] END AS numeric(18,4)) AS [pieces],
    CAST(RTRIM(d.[SiteCode]) AS nvarchar(200)) AS [site],
    CAST(RTRIM(d.[StagCode]) AS nvarchar(200)) AS [stage],
    CAST(COALESCE(NULLIF(RTRIM(h.[LocCode]), ''), NULLIF(RTRIM(d.[LocCode]), '')) AS nvarchar(200)) AS [location],
    CAST(NULL AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[fmPStTrnhed] h
  LEFT JOIN dbo.[fmPStTrnDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.fItems it ON it.ItemCode = COALESCE(d.[ItemCode], h.[ItemCode])

  UNION ALL

  SELECT
    CAST('frDispHed:' + RTRIM(h.[RefNo]) + ISNULL(':' + CAST(d.[RecordId] AS varchar(30)), '') AS nvarchar(200)) AS [lineId],
    CAST(COALESCE(m.name, N'Dispatch') AS nvarchar(200)) AS [type],
    CAST(RTRIM(h.[TxnType]) AS nvarchar(200)) AS [txnType],
    CAST('frDispHed' AS nvarchar(200)) AS [source],
    CAST(RTRIM(h.[RefNo]) AS nvarchar(200)) AS [reference],
    CAST(COALESCE(NULLIF(RTRIM(deb.[DebName]), ''), RTRIM(h.[DebCode])) AS nvarchar(200)) AS [customer],
    CAST(RTRIM(h.[RefNo1]) AS nvarchar(200)) AS [invoiceNo],
    CAST(h.[TxnDate] AS date) AS [date],
    CAST(RTRIM(d.[RefNo1]) AS nvarchar(200)) AS [jobNo],
    CAST(RTRIM(h.[ManuRef]) AS nvarchar(200)) AS [manualNo],
    CAST(RTRIM(d.[ItemCode]) AS nvarchar(200)) AS [itemCode],
    CAST(RTRIM(it.ItemName) AS nvarchar(200)) AS [itemName],
    CAST(NULL AS nvarchar(200)) AS [machine],
    CAST(COALESCE(NULLIF(d.[QtyKG], 0), d.[Qty]) AS numeric(18,4)) AS [qtyKg],
    CAST(NULL AS numeric(18,4)) AS [pieces],
    CAST(RTRIM(h.[SiteCode]) AS nvarchar(200)) AS [site],
    CAST(NULL AS nvarchar(200)) AS [stage],
    CAST(RTRIM(h.[LocCode]) AS nvarchar(200)) AS [location],
    CAST(RTRIM(h.[comcode]) AS nvarchar(200)) AS [company],
    CAST(RTRIM(h.[CostCode]) AS nvarchar(200)) AS [costCentre]
  FROM dbo.[frDispHed] h
  LEFT JOIN dbo.[frDispDet] d ON d.[RefNo] = h.[RefNo]
  LEFT JOIN dbo.[fDebtor] deb ON deb.[DebCode] = h.[DebCode]
  LEFT JOIN dbo.fItems it ON it.ItemCode = d.[ItemCode]
  LEFT JOIN txn m ON m.tbl = 'frDispHed' AND m.code = RTRIM(h.[TxnType])
;
GO

SELECT TOP 20 * FROM dbo.v_manufacturing_quick ORDER BY [date] DESC;
